#include "telemetry.h"

#include <math.h>
#include <Arduino.h>

/* 1 — values are generated by the simulator, 0 — placeholder for the real link */
#ifndef C2_SIMULATE
#define C2_SIMULATE 1
#endif

/* 14S pack: 42.0 V empty, 58.8 V full */
#define PACK_EMPTY_V 42.0f
#define PACK_FULL_V  58.8f

telemetry_t telem = {
    .voltage_v = 58.2f,
    .batt_pct = 95,
    .rf_on = true,
    .wifi_on = true,
    .starlink_on = true,
    .lte_on = false,
    .vpn_on = true,
    .sats = 14,
    .uptime_ms = 0,
};

void telemetry_update(void)
{
    telem.uptime_ms = millis();
    float t = telem.uptime_ms / 1000.0f;

#if C2_SIMULATE
    /* Slow discharge: 95 % -> 3 % during 4 minutes, then start over.
     * Enough to see the ring go green -> yellow -> red. */
    float cycle = fmodf(t, 240.0f) / 240.0f;
    float pct = 95.0f - 92.0f * cycle;

    telem.batt_pct = (uint8_t)(pct + 0.5f);
    telem.voltage_v = PACK_EMPTY_V + (pct / 100.0f) * (PACK_FULL_V - PACK_EMPTY_V);

    /* Links blink slowly, so both states are visible in the demo */
    telem.rf_on = true;
    telem.wifi_on = fmodf(t, 24.0f) < 15.0f;
    telem.starlink_on = fmodf(t, 36.0f) < 26.0f;
    telem.lte_on = fmodf(t, 48.0f) < 18.0f;
    telem.vpn_on = true;

    telem.sats = (telem.batt_pct > 0) ? (uint8_t)(12 + (int)(4.0f * sinf(t * 0.2f))) : 0;
#else
    (void)t;
#endif
}
